const fs = require('fs');
const path = require('path');

const content = fs.readFileSync('Học liệu đọc.txt', 'utf8');
const match = content.match(/src="data:image\/png;base64,([A-Za-z0-9+/=]+)/);

if (match) {
    let b64 = match[1];
    console.log('Base64 length:', b64.length);

    // Add padding
    const padding = 4 - (b64.length % 4);
    if (padding !== 4) {
        b64 += '='.repeat(padding);
    }

    const imgBuffer = Buffer.from(b64, 'base64');
    fs.writeFileSync('hinh1.png', imgBuffer);
    console.log('Image saved. Size:', imgBuffer.length, 'bytes');
} else {
    console.log('No match found');
    const idx = content.indexOf('base64,');
    if (idx >= 0) {
        const after = content.substring(idx + 7);
        console.log('After base64, first 50:', JSON.stringify(after.substring(0, 50)));

        // Check for invalid chars
        const validChars = new Set('ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/='.split(''));
        for (let i = 0; i < after.length; i++) {
            if (!validChars.has(after[i])) {
                console.log('First invalid char at pos', i, ':', JSON.stringify(after[i]));
                console.log('Context:', JSON.stringify(after.substring(Math.max(0, i-10), i+10)));
                break;
            }
        }

        // If all chars valid, use full string
        let b64 = after.replace(/[\x00\s]+$/, '');
        const padding = 4 - (b64.length % 4);
        if (padding !== 4) {
            b64 += '='.repeat(padding);
        }
        const imgBuffer = Buffer.from(b64, 'base64');
        fs.writeFileSync('hinh1.png', imgBuffer);
        console.log('Image saved. Size:', imgBuffer.length, 'bytes');
    }
}

const fs = require('fs');

const content = fs.readFileSync('Học liệu đọc.txt', 'utf8');
const b64Index = content.indexOf('base64,');
const beforeImg = content.substring(0, b64Index + 7);

// Extract text content before the image
console.log('=== CONTENT BEFORE IMAGE ===');
console.log(beforeImg);
console.log('==========');

// Show what sections/paragraphs exist
const paragraphStarts = [];
let idx = 0;
while (true) {
    const pStart = content.indexOf('<p ', idx);
    if (pStart === -1) break;
    paragraphStarts.push(pStart);
    idx = pStart + 1;
}
console.log('Paragraph tags:', paragraphStarts.length);

// Extract section headings
const headingMatches = content.match(/<strong><span[^>]*>([^<]+)<\/span><\/span><\/span><\/strong>/g);
if (headingMatches) {
    headingMatches.forEach(h => {
        const textMatch = h.match(/>([^<]+)</);
        if (textMatch) console.log('Heading:', textMatch[1]);
    });
}

/* =============================================
   Học liệu đọc: Tổng quan về bữa ăn và dinh dưỡng
   Style Sheet
   ============================================= */

body {
    font-family: "Times New Roman", Times, serif;
    font-size: 13pt;
    color: #303030;
    line-height: 1.6;
    margin: 30px auto;
    max-width: 800px;
    padding: 0 20px;
    background-color: #ffffff;
}

/* Container chính */
.document-container {
    width: 100%;
}

/* Tiêu đề chính */
.main-title {
    text-align: center;
    font-weight: bold;
    font-size: 18pt;
    color: #303030;
    margin-bottom: 20px;
    line-height: 1.4;
}

/* Thông tin học liệu */
.doc-info {
    text-align: justify;
    font-size: 13pt;
    color: #303030;
    margin-bottom: 20px;
}

.doc-info .label {
    font-weight: bold;
}

/* Các đoạn văn */
.content-text {
    text-align: justify;
    font-size: 13pt;
    color: #303030;
    margin-bottom: 15px;
    line-height: 1.6;
}

/* Section heading */
.section-heading {
    font-weight: bold;
    font-size: 13pt;
    color: #303030;
    margin-bottom: 10px;
    margin-top: 20px;
}

/* Hình ảnh */
.content-image {
    display: block;
    margin: 20px auto;
    max-width: 100%;
    height: auto;
}

/* Highlight / strong */
strong {
    font-weight: bold;
}
